// Regenerates lib/journal/posts/all.ts: one import per post file, so a new
// post only needs its file. Run after adding posts: node scripts/journal-barrel.mjs
import { readdirSync, writeFileSync } from "node:fs";

const dir = new URL("../lib/journal/posts/", import.meta.url);
const files = readdirSync(dir).filter((f) => f.endsWith(".ts") && f !== "all.ts").sort();
const id = (f) => "p_" + f.replace(/\.ts$/, "").replace(/\W+/g, "_");
const out = [
  "// Generated by scripts/journal-barrel.mjs – do not edit.",
  'import type { Post } from "@/lib/journal/types";',
  "",
  ...files.map((f) => `import { post as ${id(f)} } from "./${f.replace(/\.ts$/, "")}";`),
  "",
  `export const POSTS: Post[] = [${files.map(id).join(", ")}];`,
  "",
].join("\n");
writeFileSync(new URL("all.ts", dir), out);
console.log(`${files.length} posts`);
